  "track.coroutines.m.jobtree.s.fail.explainSup": "{job} thất bại và hủy con của nó. Lỗi chỉ dừng ở mức con trực tiếp của `supervisorScope`; scope và các con khác vẫn sống.",
  "track.coroutines.m.jobtree.s.noop.explain": "Job này không còn hoạt động nên thao tác không đổi gì.",
  "track.coroutines.m.jobtree.s.children.title": "Khi nào Job đang hủy thành đã hủy?",
  "track.coroutines.m.jobtree.s.children.explain": "Job ở trạng thái đang hủy đợi các con kết thúc. Khi con đã xong, Job chuyển sang đã hủy.",
  "track.coroutines.m.jobtree.s.settle.title": "Các Job còn lại kết thúc ra sao?",
  "track.coroutines.m.jobtree.s.settle.explain": "Các Job còn sống chạy hết thân hàm và hoàn tất từ lá lên gốc. Job đã hủy hay thất bại giữ nguyên trạng thái cuối của nó.",
  "track.coroutines.m.jobtree.co.try": "Chọn `coroutineScope`, cho grandchild ném exception rồi đổi sang `supervisorScope` và so kết quả.",
  "track.coroutines.m.jobtree.co.propagate": "Lỗi của một con (Job thường) làm fail cha và hủy các con khác. Đây là structured concurrency, không phải lỗi của thư viện. [[src:kt-exceptions]]",
  "track.coroutines.m.jobtree.co.supervisor": "`supervisorScope` lan truyền hủy theo một chiều và chỉ hủy các con khi chính nó fail; nó vẫn đợi mọi con trước khi kết thúc. [[src:kt-exceptions]]",
  "track.coroutines.m.jobtree.co.cancelChild": "Hủy một con không hủy cha: hủy đi xuống, không đi lên. Khi cha bị hủy, mọi con bị hủy đệ quy. [[src:kt-context]] [[src:kt-exceptions]]",
